/**
 * Бюджет початкового JavaScript (PERFORMANCE-v9 § 1, § 1.1, § 10.1).
 *
 * Запускається після `npm run build`. Вихід ≠ 0 — перевищення бюджету.
 *
 * ЧОМУ НЕ ШАБЛОН ІЗ КАНОНУ. § 10.1 пропонує підсумувати `build/_app/immutable/
 * entry/*.js`. У цьому проєкті там лежать два файли-завантажувачі на 2 КБ
 * gzip разом — гейт із порогом 150 КБ над ними не впав би НІКОЛИ, скільки б
 * коду не приїхало на сторінку. Це рівно той клас, від якого застерігає сам
 * канон: перевірка, що дивиться поруч із дефектом і лишається зеленою
 * назавжди (AI-AGENT-PITFALLS-v9 § 1.1).
 *
 * Тому міряється те, що браузер справді тягне на першу сторінку: усі `.js`,
 * на які посилається `build/index.html` — і `<script src>`, і `modulepreload`.
 * Саме цей набір визначає, коли сторінка стане інтерактивною.
 *
 * КОД І ДАНІ — ДВА РІЗНІ ЧИСЛА (PERF-BUDGET-CODE-VS-DATA, канон v9).
 *
 * Доти тут стояло ОДНЕ сумарне число, і воно рахувало разом код і 42 словники
 * перекладів. Наслідок не теоретичний і записаний у журналі нижче: 2026-08-28
 * бюджет довелося підняти 240 → 245, бо в словники приїхало 798 рядків назв
 * керувань. Коду не додали НІ РЯДКА — почервонів продуктивнісний гейт від
 * доданого ВМІСТУ. Обмін тоді назвали правильно (ACCESSIBILITY та I18N —
 * HIGH, PERFORMANCE — MEDIUM), але сам вибір «або читалка вимовляє
 * англійською, або червоний бюджет» був фальшивим: бюджет ставлять, щоб
 * ловити розростання КОДУ.
 *
 * Тепер стель три:
 *
 *   CODE_KB                 усе, крім чанка словників. Тісна: приріст тут —
 *                           це нова залежність або новий екран, і його треба
 *                           побачити одразу;
 *   DATA_KB                 чанк словників. Підняти її — рутина: у 42 мовах
 *                           побільшало тексту, це видно й це нормально
 *                           (канон: подвоєння бази має бути ВИДНО, а не
 *                           заблоковано). Підняти CODE_KB — це рішення, яке
 *                           вимагає обґрунтування;
 *   LARGEST_CODE_CHUNK_KB   найбільший окремий чанк КОДУ. Доти найбільшим
 *                           чанком завжди був словниковий, тобто це число
 *                           повторювало DATA і про код не казало нічого.
 *
 * ЯК ВІДРІЗНЯЄТЬСЯ ЧАНОК ДАНИХ. Не за іменем (воно хешоване) і не за розміром,
 * а за ВМІСТОМ: із кожного `src/lib/i18n/locales/*.ts` береться довге
 * унікальне значення рядка, і шукається в самих файлах збірки. Тобто маркер
 * приходить із джерел, а не з припущення про структуру `build/`. Якщо маркерів
 * знайдено менше за поріг — чанкування змінилося, і гейт мусить УПАСТИ, а не
 * порахувати всі словники як код (PERF-BUDGET-CODE-VS-DATA: «зниклий маркер
 * реєстру означає мертву перевірку»).
 *
 * НАПРЯМОК ПОХИБКИ НАЗВАНИЙ. Разом зі словниками в тому самому чанку лежить
 * `I18nState.svelte.ts` — тобто DATA трохи ЗАВИЩЕНО, а CODE на ту саму дещицю
 * занижено. Величина обмежена розміром самого контролера (одиниці кілобайт
 * мініфікованого коду). Захист від того, щоб у цей чанк тихо переїхав справжній
 * код: DATA — теж ратчет, лише просторіший, тож помітний приріст коду в ньому
 * впаде на DATA замість CODE, а не зникне.
 */
import { readFileSync, existsSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { gzipSync } from "node:zlib";

const BUILD = "build";
const ENTRY_HTML = join(BUILD, "index.html");
const LOCALES_DIR = join("src", "lib", "i18n", "locales");

/**
 * Стеля КОДУ в КБ gzip — усе, крім чанка словників. Виміряно цим скриптом:
 *
 *   116  2026-09-10  перший замір після поділу коду й даних (сума була 242)
 *
 * Журнал СУМАРНОГО числа, яке тут стояло доти, лишається як історія — саме він
 * і став аргументом за поділ:
 *
 *   242  2026-08-16
 *   244  2026-08-19  маршрут `/beta-test-checklists/` додав два кілобайти в
 *                    маніфест роутера; сама сторінка окремим чанком
 *   228  2026-08-27  `zod` пішов із бандла — він перевіряв літерали,
 *                    які вже перевірив компілятор
 *   235  2026-08-27  шість повідомлень про збій AI × 42 словники
 *   242  2026-08-28  дев'ятнадцять назв керувань × 42 словники
 *
 * Із п'яти рядків журналу ТРИ — це приріст словників, тобто вмісту. Саме тому
 * стеля коду тепер окрема: вона рухається лише вниз, і кожен її підйом — це
 * рішення про код, а не побічний ефект перекладу.
 *
 * Запас понад зміряним — два кілобайти, а не шість: бюджет уже стояв на 250
 * при зміряних 244, і цей запас був тихим дозволом відрости.
 */
const CODE_KB = 118;

/**
 * Стеля ДАНИХ у КБ gzip — чанк із усіма 42 словниками. Виміряно:
 *
 *   126  2026-09-10  перший окремий замір
 *   129  2026-09-10  три рядки в 42 мовах: ім'я кнопки «надіслати» в чаті AI,
 *                    попередження про машинний переклад у меню мов і підпис
 *                    службового знака версії. Усі три доти були англійськими
 *                    (або відсутніми) в усіх 42 мовах
 *   130  2026-09-10  `alt` прев'ю резюме — четвертий такий рядок; доти він жив
 *                    літералом у `config/cvDownloads.ts`, тобто поза словником
 *   133  2026-09-17  десята картка портфоліо (Adopt an Animal) у 42 словниках:
 *                    назва, опис, підпис кнопки й стек. Росте тут майже сам
 *                    ОПИС: назва та стек однакові в усіх мовах, а підпис кнопки
 *                    скопійовано з сусіднього запису — три поля з чотирьох gzip
 *                    стискає майже в нуль, і платимо ми за 42 унікальні речення
 *
 * ДЛЯ ЧОГО ПОДІЛ І РОБИВСЯ — видно рівно тут. Ці +3 КБ це переклад, і при
 * старому сумарному числі вони знову впали б на продуктивнісний бюджет: сума
 * пішла 242 → 245, тобто в стелю 245, яка стояла до поділу. Код при цьому
 * не змінився ні на кілобайт — 116 до і 116 після.
 *
 * Це число теж рухається лише вниз, але піднімати його ДЕШЕВО й це передбачено:
 * рядок у 42 мовах — це вміст, який комусь потрібен, а не борг. Різниця з
 * CODE_KB не в суворості механізму, а в ціні рішення.
 *
 * СПРАВЖНІЙ ЗАПАС ЛЕЖИТЬ ТУТ, І ВІН ВЕЛИКИЙ. Із цього числа відвідувач читає
 * РІВНО ОДНУ мову з 42, тобто майже все воно — текст решти 41. Ліниве
 * завантаження словника прибрало б приблизно половину всього початкового JS. Не зроблено навмисно: `t` — модульний
 * синглтон, а зсув мов від модульного синглтона під час prerender цей проєкт
 * уже проходив (SEO-v9 § 1.4). Записано в PROJECT-CONTEXT.md як борг із числом.
 *
 * Що перевірено перед тим, як приймати це число: зі словників уже прибрано
 * 1148 рядків дублювання (`id`, `category`, `image`, `featured` — 369 копій
 * дев'яти значень). Виграш виявився 0,5 КБ: gzip і так стискав сорок одну
 * копію одного рядка майже в нуль. Дешевого способу відіграти їх у словниках
 * НЕМАЄ — унікальний текст 41 мови не стискається.
 */
const DATA_KB = 133;

/**
 * Найбільший окремий чанк КОДУ. Ловить те, чого не видно в сумі: одна
 * залежність, яка тихо подвоїлася, поки решта худла.
 *
 *   55  2026-09-10  `nodes/0` — макет із усіма секціями сторінки
 *
 * Доти тут стояло `LARGEST_CHUNK_KB = 128`, і воно міряло словниковий чанк —
 * тобто дублювало DATA і про код не казало НІЧОГО.
 */
const LARGEST_CODE_CHUNK_KB = 57;

/**
 * Скільки словникових маркерів мусить знайтися, щоб класифікація вважалася
 * живою. Менше — чанкування змінилося (або словники поїхали лінивими чанками,
 * що само по собі добра новина, але вимагає переписати саме цей скрипт).
 */
const MIN_MARKERS = 40;

if (!existsSync(ENTRY_HTML)) {
	console.error(`Немає ${ENTRY_HTML} — спершу \`npm run build\`.`);
	process.exit(1);
}

/**
 * Довгі унікальні значення рядків із кожного словника — по одному на мову.
 * Маркер приходить із ДЖЕРЕЛА, тому не залежить від імен файлів у `build/`.
 */
function localeMarkers() {
	const markers = [];
	for (const name of readdirSync(LOCALES_DIR)) {
		if (!name.endsWith(".ts")) continue;
		const source = readFileSync(join(LOCALES_DIR, name), "utf8");
		// `chatPlaceholder` — довгий, свій у кожній мові, без лапок і зворотних
		// слешів усередині, тобто в бандлі лежить байт у байт.
		const hit = source.match(/chatPlaceholder:\s*"([^"\\]{12,})"/);
		if (hit) markers.push(hit[1]);
	}
	return markers;
}

const markers = localeMarkers();
if (markers.length < MIN_MARKERS) {
	console.error(
		`У ${LOCALES_DIR} знайдено лише ${markers.length} маркерів словників — ` +
			`перевірка мертва, змінилася форма файлів локалей?`
	);
	process.exit(1);
}

const html = readFileSync(ENTRY_HTML, "utf8");

// І `<script src>`, і `<link rel="modulepreload">`: браузер тягне обидва до
// того, як сторінка стане інтерактивною.
const refs = [...html.matchAll(/(?:href|src)="\.(\/_app\/[^"]*\.js)"/g)].map((m) => m[1]);
const unique = [...new Set(refs)];

// Перевірка, яка захищає перевірку: якщо структура build/ зміниться і регулярка
// перестане знаходити файли, гейт мусить УПАСТИ, а не відзвітувати нуль.
if (unique.length < 5) {
	console.error(
		`Знайдено лише ${unique.length} JS-посилань у ${ENTRY_HTML} — перевірка мертва, ` +
			`структура build/ змінилася?`
	);
	process.exit(1);
}

/** @type {{ ref: string, gz: number, hits: number }[]} */
const chunks = [];
for (const ref of unique) {
	const path = join(BUILD, ref);
	if (!existsSync(path)) {
		console.error(`${ENTRY_HTML} посилається на ${ref}, якого немає у build/`);
		process.exit(1);
	}
	const bytes = readFileSync(path);
	const text = bytes.toString("utf8");
	chunks.push({
		ref,
		gz: gzipSync(bytes).length,
		hits: markers.filter((marker) => text.includes(marker)).length
	});
}

const markersFound = chunks.reduce((sum, c) => sum + c.hits, 0);
if (markersFound < MIN_MARKERS) {
	console.error(
		`У початковому JS знайдено лише ${markersFound} із ${markers.length} словникових ` +
			`маркерів. Це або добра новина (словники поїхали лінивим чанком), або мертва\n` +
			`класифікація — і в обох випадках цей скрипт треба переписати, а не лишати\n` +
			`рахувати дані як код.`
	);
	process.exit(1);
}

// Чанк даних несе десятки маркерів; поодинокий збіг у чанку коду (наприклад,
// той самий рядок у SSR-розмітці) не робить його словниковим.
const data = chunks.filter((c) => c.hits >= 2);
const code = chunks.filter((c) => c.hits < 2);

const kb = (bytes) => Math.round(bytes / 1024);
const dataKb = kb(data.reduce((sum, c) => sum + c.gz, 0));
const codeKb = kb(code.reduce((sum, c) => sum + c.gz, 0));
const codeSorted = [...code].sort((a, b) => b.gz - a.gz);
const largestCodeKb = kb(codeSorted[0].gz);

console.log(
	`Початковий JS: ${codeKb + dataKb} КБ gzip у ${unique.length} файлах — ` +
		`код ${codeKb} (бюджет ${CODE_KB}), дані ${dataKb} (бюджет ${DATA_KB}).`
);
console.log(`  дані: ${data.length} чанк(и) зі словниками, ${markersFound} маркерів`);
for (const { ref, gz } of codeSorted.slice(0, 3)) {
	console.log(`  код:  ${(gz / 1024).toFixed(1)} КБ  ${ref}`);
}

/**
 * ДОПУСК, а не точна рівність (CI-CD-AND-TOOLS-v9 § 1.18.1).
 *
 * Гейт порівнює ЗМІРЯНЕ число з порогом, а вимір залежить від машини. Заміряно
 * в `teatralo4ka` 2026-09-16: деплой упав на «758 КБ > 758», тоді як локальна
 * збірка ТОГО САМОГО дерева дала 757.78 — кількасот байтів різниці між
 * раннерами, тобто більше за типовий запас. Без допуску такий збіг червонить
 * прогін без жодної зміни в коді.
 *
 * Кілобайт перекриває цей розкид і НЕ перекриває справжній приріст: реальна
 * правка важить кілобайти. Число стоїть іменованою сталою навмисно — сховане
 * в порівнянні, воно читалося б як «поріг точний».
 */
const TOLERANCE_KB = 1;

const problems = [];
if (codeKb > CODE_KB + TOLERANCE_KB) {
	problems.push(`КОД ${codeKb} КБ gzip перевищує бюджет ${CODE_KB} КБ (допуск ${TOLERANCE_KB})`);
}
if (dataKb > DATA_KB + TOLERANCE_KB) {
	problems.push(`ДАНІ ${dataKb} КБ gzip перевищують бюджет ${DATA_KB} КБ (допуск ${TOLERANCE_KB})`);
}
if (largestCodeKb > LARGEST_CODE_CHUNK_KB + TOLERANCE_KB) {
	problems.push(
		`найбільший чанк коду ${largestCodeKb} КБ gzip (${codeSorted[0].ref}) ` +
			`перевищує ${LARGEST_CODE_CHUNK_KB} КБ (допуск ${TOLERANCE_KB})`
	);
}

if (problems.length > 0) {
	console.error("\nБюджет перевищено:");
	for (const p of problems) console.error(`  • ${p}`);
	console.error(
		"\nЦі числа рухаються лише вниз. Приріст ДАНИХ — рутина: підняти DATA_KB разом\n" +
			"із рядком у журналі. Приріст КОДУ — рішення: спершу подивитися, що саме\n" +
			"приїхало, і лише потім підіймати CODE_KB із причиною в PROJECT-CONTEXT.md."
	);

	/**
	 * БЮДЖЕТ ЗВІТУЄ, АЛЕ НЕ ЗУПИНЯЄ ВИПУСК (CI-CD-AND-TOOLS-v9 § 1.18).
	 *
	 * `BUDGET_SOFT=1` ставить рівно одне місце — крок збірки в `deploy.yml`.
	 * Причина не в тому, що бюджет менш важливий, а в тому, ЩО САМЕ він
	 * перериває: деплой возить виправлення тексту, нові знімки й дані, на які
	 * чекають люди, і тримати їх через пів кілобайта чанка означає платити за
	 * швидкість сторінки її відсутністю. Заміряно на прогоні 35196420932: випуск
	 * зупинило +2 КБ ПЕРЕКЛАДУ — коду не додано ні рядка.
	 *
	 * Локально — теж лише звіт, і це не м'якість. Перевищення посеред задачі
	 * уриває роботу й змушує розбиратися зі стелею замість того, що робили.
	 * Голосний рядок на екрані цієї роботи не спиняє.
	 *
	 * ЖОРСТКО те саме число перевіряє `.github/workflows/budgets.yml` — окремий
	 * прогін на тому самому `push`, паралельно з деплоєм. Перевищення не зникає;
	 * воно перестає бути заручником випуску. Гейт, який після винесення ніде не
	 * падає, не винесений, а вимкнений, — тому той прогін падає по-справжньому.
	 */
	if (process.env.BUDGET_SOFT === "1" || process.env.CI !== "true") {
		console.error(
			"\n  ⚠️  не зупиняємо: тут бюджет лише звітує, жорстко його перевіряє прогін «Budgets»."
		);
		process.exit(0);
	}

	process.exit(1);
}
